<template>
  <div id="register" v-title data-title="卫星地面融合网络社区-注册">
    <!--<video preload="auto" class="me-video-player" autoplay="autoplay" loop="loop">
          <source src="../../static/vedio/sea.mp4" type="video/mp4">
      </video>-->

    <div class="me-login-box me-login-box-radius">
      <div class="me-back-button">
        <el-button type="text" icon="el-icon-arrow-left" @click="goBack">返回</el-button>
      </div>
      <h1>卫星地面融合网络社区-注册</h1>

      <el-form ref="userForm" :model="userForm" :rules="rules">
        <el-form-item prop="account">
          <el-input placeholder="用户名" v-model="userForm.account"></el-input>
          <div class="me-form-hint">用户名为今后登录账号</div>
        </el-form-item>

        <el-form-item prop="nickname">
          <el-input placeholder="昵称" v-model="userForm.nickname"></el-input>
        </el-form-item>

        <el-form-item prop="email">
          <el-input placeholder="邮箱" v-model="userForm.email"></el-input>
        </el-form-item>

        <el-form-item prop="password">
          <el-input placeholder="密码" v-model="userForm.password" type="password" show-password></el-input>
        </el-form-item>

        <el-form-item prop="confirmPassword">
          <el-input placeholder="再次输入密码" v-model="userForm.confirmPassword" type="password" show-password></el-input>
        </el-form-item>

        <el-form-item prop="code">
          <el-row :gutter="10">
            <el-col :span="16">
              <el-input placeholder="验证码" v-model="userForm.code"></el-input>
            </el-col>
            <el-col :span="8">
              <el-button type="primary" :disabled="countdown > 0" @click="getCode">
                {{ countdown > 0 ? `${countdown}秒后重新获取` : '获取验证码' }}
              </el-button>
            </el-col>
          </el-row>
        </el-form-item>

        <el-form-item size="small" class="me-login-button">
          <el-button type="primary" @click.native.prevent="register('userForm')">注册</el-button>
        </el-form-item>
      </el-form>

      <div class="me-login-design">
        <p>Designed by
          <strong>
            <router-link to="/" class="me-login-design-color">coconut</router-link>
          </strong>
        </p>
      </div>

    </div>
  </div>
</template>

<script>
  import {register, sendEmailCode} from '@/api/login'

  export default {
    name: 'Register',
    data() {
      return {
        userForm: {
          account: '',
          nickname: '',
          email: '',
          password: '',
          confirmPassword: '',
          code: ''
        },
        rules: {
          account: [
            {required: true, message: '请输入用户名', trigger: 'blur'},
            {min: 3, max: 10, message: '用户名长度在3-10个字符之间', trigger: 'blur'}
          ],
          nickname: [
            {required: true, message: '请输入昵称', trigger: 'blur'},
            {min: 2, max: 10, message: '昵称长度在2-10个字符之间', trigger: 'blur'}
          ],
          email: [
            {required: true, message: '请输入邮箱', trigger: 'blur'},
            {type: 'email', message: '请输入正确的邮箱格式', trigger: 'blur'}
          ],
          password: [
            {required: true, message: '请输入密码', trigger: 'blur'},
            {min: 8, max: 20, message: '密码长度在8-20个字符之间', trigger: 'blur'},
            {pattern: /^(?=.*[A-Z])(?=.*\d)[A-Za-z\d]+$/, message: '密码须为字母数字混合，且至少包含一个大写字母', trigger: 'blur'}
          ],
          confirmPassword: [
            {required: true, message: '请再次输入密码', trigger: 'blur'},
            {validator: this.validatePassword, trigger: 'blur'}
          ],
          code: [
            {required: true, message: '请输入验证码', trigger: 'blur'},
            {length: 6, message: '验证码长度为6位', trigger: 'blur'}
          ]
        },
        countdown: 0
      }
    },
    methods: {
      goBack() {
        this.$router.back()
      },
      validatePassword(rule, value, callback) {
        if (value !== this.userForm.password) {
          callback(new Error('两次输入的密码不一致'));
        } else {
          callback();
        }
      },
      getCode() {
        const that = this;
        // 验证邮箱格式
        const emailRule = this.rules.email;
        let isValid = true;
        for (const rule of emailRule) {
          if (rule.required && !that.userForm.email) {
            this.$message.error('请输入邮箱');
            isValid = false;
            break;
          }
          if (rule.type === 'email') {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(that.userForm.email)) {
              this.$message.error('请输入正确的邮箱格式');
              isValid = false;
              break;
            }
          }
        }
        
        if (isValid) {
          sendEmailCode(that.userForm.email).then(response => {
            if (response.code === 0) {
              that.$message.success('验证码已发送到您的邮箱');
              const code = response.data.code;
              console.log('【测试模式】验证码已生成');
              console.log('邮箱: ' + that.userForm.email);
              console.log('验证码: ' + code);
              // 开始倒计时
              that.countdown = 60;
              const timer = setInterval(() => {
                that.countdown--;
                if (that.countdown <= 0) {
                  clearInterval(timer);
                }
              }, 1000);
            } else {
              that.$message.error(response.msg || '发送失败');
            }
          }).catch(error => {
            that.$message.error('发送失败，请稍后重试');
          });
        }
      },
      register(formName) {
        let that = this
        this.$refs[formName].validate((valid) => {
          if (valid) {
            that.$store.dispatch('register', that.userForm).then(() => {
              that.$message({message: '注册成功 快写文章吧', type: 'success', showClose: true});
              that.$router.push({path: '/'})
            }).catch((error) => {
              if (error !== 'error') {
                that.$message({message: error, type: 'error', showClose: true});
              }
            })

          } else {
            return false;
          }
        });

      }

    }
  }
</script>

<style scoped>
  #login {
    min-width: 100%;
    min-height: 100%;
  }

  .me-video-player {
    background-color: transparent;
    width: 100%;
    height: 100%;
    object-fit: fill;
    display: block;
    position: absolute;
    left: 0;
    z-index: 0;
    top: 0;
  }

  .me-login-box {
    position: absolute;
    width: 480px;
    min-height: 560px;
    background-color: white;
    margin-top: 60px;
    margin-left: -270px;
    left: 50%;
    padding: 40px;
  }

  .me-login-box-radius {
    border-radius: 10px;
    box-shadow: 0px 0px 1px 1px rgba(161, 159, 159, 0.1);
  }

  .me-back-button {
    text-align: left;
    margin-bottom: 10px;
  }

  .me-back-button .el-button {
    padding: 0;
    font-size: 14px;
    color: #999;
  }

  .me-back-button .el-button:hover {
    color: #5FB878;
  }

  .me-login-box h1 {
    text-align: center;
    font-size: 24px;
    margin-bottom: 20px;
    vertical-align: middle;
  }

  .me-login-design {
    text-align: center;
    font-family: 'Open Sans', sans-serif;
    font-size: 18px;
  }

  .me-login-design-color {
    color: var(--primary-color) !important;
  }

  .me-login-button {
    text-align: center;
  }

  .me-login-button button {
    width: 100%;
  }

  .me-form-hint {
    font-size: 11px;
    color: #999;
    margin-top: 2px;
    font-style: italic;
  }

  .el-form-item {
    margin-bottom: 18px;
  }

  .el-form-item__label {
    font-weight: 500;
  }

  h1 {
    color: var(--secondary-color);
    margin-bottom: 30px;
  }

</style>



